export default function (pi: any) {
  pi.registerCommand("mark", { description: "Mark the session", handler: async (_args: string, ctx: any) => {
    const entries = ctx.sessionManager.getEntries();
    const firstUser = entries.find((entry: any) => entry.type === "message" && entry.message.role === "user");
    pi.appendEntry("probe", { n: 1, text: "caf\u00e9 <&>" });
    pi.appendEntry("bare");
    pi.setLabel(firstUser.id, "start");
    pi.setSessionName("Marked");
  } });
}

